/* ExoLens — 系外行星多维探索台
 * cell-j13-s10 (explore × dimensional-space)
 * 维度切换不重置认知：投影状态与过滤/选中状态分属独立语义，切通道只写投影。
 * 过滤/投影状态有归属且可回退：线性 op log + 指针，undo/redo/回退到任意步。
 */
'use strict';
(function () {
  /* ---------- 基础数据 ---------- */
  var DATA = window.EXO_DATA;
  if (!DATA || !DATA.records) { throw new Error('EXO_DATA 缺失：数据未内联'); }
  var RECORDS = DATA.records;

  var INSTR = {
    'Kepler': ['Kepler 光度计'],
    'K2': ['K2 光度计'],
    'TESS': ['TESS 光度计'],
    'CoRoT': ['CoRoT 光度计'],
    '地基巡天': ['HARPS 光谱仪', 'NRES 光谱仪', 'WFCAM 测光'],
  };
  function instrumentOf(rec) {
    var list = INSTR[rec.ms] || ['—'];
    return list[rec.i % list.length];
  }
  function hostOf(name) { return name.replace(/ [b-g]$/, ''); }

  var DIMS = {
    me: { label: '发现方法', type: 'cat', group: 'cat', order: ['凌星法', '视向速度法', '凌星时间变幅法', '微引力透镜法', '直接成像法', '天体测量法'] },
    ty: { label: '恒星类型', type: 'cat', group: 'cat', order: ['M型', 'K型', 'G型', 'F型', 'A型'] },
    pc: { label: '行星类别', type: 'cat', group: 'cat', order: ['类地', '超级地球', '海王星级', '木星级'] },
    ms: { label: '发现任务', type: 'cat', group: 'cat', order: ['Kepler', 'K2', 'TESS', 'CoRoT', '地基巡天'] },
    r: { label: '行星半径', type: 'num', group: 'num', unit: 'R⊕', fmt: 2 },
    p: { label: '轨道周期', type: 'num', group: 'num', unit: '天', fmt: 1 },
    t: { label: '平衡温度', type: 'num', group: 'num', unit: 'K', fmt: 0 },
    m: { label: '行星质量', type: 'num', group: 'num', unit: 'M⊕', fmt: 1 },
    d: { label: '距地距离', type: 'num', group: 'num', unit: '光年', fmt: 0 },
    yr: { label: '发现年份', type: 'num', group: 'num', unit: '', fmt: 0 },
    f: { label: '恒星金属丰度', type: 'num', group: 'num', unit: '[Fe/H]', fmt: 2 },
    e: { label: '轨道偏心率', type: 'num', group: 'num', unit: '', fmt: 2 },
  };
  var ALL_DIMS = Object.keys(DIMS);

  /* 调色板（dataviz 参考色板 · dark 步，已对 #1a1a19 表面验证；散点 all-pairs 场景 >3 类时以形状作次级编码） */
  var CAT_COLORS = ['#3987e5', '#d95926', '#199e70', '#c98500', '#d55181', '#008300'];
  var SHAPES = ['circle', 'triangle', 'square', 'diamond', 'cross', 'ring'];
  var SHAPE_NAMES = { circle: '●', triangle: '▲', square: '■', diamond: '◆', cross: '✕', ring: '○' };
  var SEQ_LO = [24, 79, 149], SEQ_HI = [205, 226, 251]; // #184f95 → #cde2fb（暗面顺序：低→深，高→浅）
  function seqColor(t) {
    t = Math.max(0, Math.min(1, t));
    var c = [0, 1, 2].map(function (i) { return Math.round(SEQ_LO[i] + (SEQ_HI[i] - SEQ_LO[i]) * t); });
    return 'rgb(' + c.join(',') + ')';
  }
  function colorOf(dimKey, value) {
    var dim = DIMS[dimKey];
    if (dim.type === 'cat') {
      var vs = catValues(dimKey), idx = vs.indexOf(value);
      return CAT_COLORS[Math.max(0, idx) % CAT_COLORS.length];
    }
    var ext = EXTENTS[dimKey];
    return seqColor((value - ext.lo) / (ext.hi - ext.lo));
  }
  function shapeOf(dimKey, value) {
    if (DIMS[dimKey].type !== 'cat') return 'circle';
    var vs = catValues(dimKey), idx = vs.indexOf(value);
    return SHAPES[Math.max(0, idx) % SHAPES.length];
  }

  /* ---------- 状态：线性 op log + 指针（唯一状态 owner = session trail store） ---------- */
  var state = { pointer: -1, ops: [], opSeq: 0 };
  var UI = { expandedDim: null, brush: null, hoverId: null, popoverOpId: null, tableView: false };

  var DEFAULT_CH = { x: 'p', y: 'r', color: 'pc', size: 'm' };

  function replay(p) {
    var st = { ch: { x: DEFAULT_CH.x, y: DEFAULT_CH.y, color: DEFAULT_CH.color, size: DEFAULT_CH.size }, filters: {}, sel: null };
    for (var i = 0; i <= p && i < state.ops.length; i++) {
      var op = state.ops[i];
      if (op.disabled) continue;
      if (op.type === 'projection') st.ch[op.channel] = op.dim;
      else if (op.type === 'filter') st.filters[op.dim] = op.spec;
      else if (op.type === 'filterClear') delete st.filters[op.dim];
      else if (op.type === 'select') st.sel = op.ids;
    }
    return st;
  }

  function matchesFilters(rec, filters) {
    for (var dimKey in filters) {
      var spec = filters[dimKey];
      if (spec.kind === 'values') { if (spec.values.indexOf(rec[dimKey]) < 0) return false; }
      else { if (rec[dimKey] < spec.lo - 1e-9 || rec[dimKey] > spec.hi + 1e-9) return false; }
    }
    return true;
  }

  /* ---------- 工具 ---------- */
  function $(id) { return document.getElementById(id); }
  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text != null) e.textContent = text;
    return e;
  }
  function fmtVal(v, dimKey) {
    var dim = DIMS[dimKey];
    if (v == null || isNaN(v)) return '—';
    if (dim.type === 'num') {
