      var excluded = all.filter(function (v) { return spec.values.indexOf(v) < 0; });
      if (excluded.length > 0 && excluded.length <= 2) return label + '：排除 ' + excluded.join('、');
      return label + '：仅 ' + (spec.values.length <= 3 ? spec.values.join('、') : spec.values.length + ' 个值');
    }
    var loTxt = spec.lo <= EXTENTS[dimKey].lo + 1e-9 ? null : '≥ ' + fmtVal(spec.lo, dimKey);
    var hiTxt = spec.hi >= EXTENTS[dimKey].hi - 1e-9 ? null : '≤ ' + fmtVal(spec.hi, dimKey);
    if (loTxt && hiTxt) return label + '：' + loTxt + ' 且 ' + hiTxt;
    if (loTxt) return label + '：' + loTxt;
