/* ExoLens — 系外行星多维探索台
 * cell-j13-s10 (explore × dimensional-space)
 * 维度切换不重置认知：投影状态与过滤/选中状态分属独立语义，切通道只写投影。
 * 过滤/投影状态有归属且可回退：线性 op log + 指针，undo/redo/回退到任意步。
 */
'use strict';
(function () {
  /* ---------- 基础数据 ---------- */
  var DATA = window.EXO_DATA;
  if (!DATA || !DATA.records) { throw new Error('EXO_DATA 缺失：数据未内联'); }
  var RECORDS = DATA.records;

  var INSTR = {
    'Kepler': ['Kepler 光度计'],
    'K2': ['K2 光度计'],
    'TESS': ['TESS 光度计'],
    'CoRoT': ['CoRoT 光度计'],
    '地基巡天': ['HARPS 光谱仪', 'NRES 光谱仪', 'WFCAM 测光'],
  };
  function instrumentOf(rec) {
    var list = INSTR[rec.ms] || ['—'];
    return list[rec.i % list.length];
  }
  function hostOf(name) { return name.replace(/ [b-g]$/, ''); }

  var DIMS = {
    me: { label: '发现方法', type: 'cat', group: 'cat', order: ['凌星法', '视向速度法', '凌星时间变幅法', '微引力透镜法', '直接成像法', '天体测量法'] },
    ty: { label: '恒星类型', type: 'cat', group: 'cat', order: ['M型', 'K型', 'G型', 'F型', 'A型'] },
