    if (DIMS[k].type !== 'num') return;
    var lo = Infinity, hi = -Infinity;
    RECORDS.forEach(function (r) { var v = r[k]; if (v < lo) lo = v; if (v > hi) hi = v; });
    var pad = (hi - lo) * 0.04 || 0.5;
