  var CAT_AXIS = {};
  ALL_DIMS.forEach(function (k) { if (DIMS[k].type === 'cat') CAT_AXIS[k] = catValues(k); });

  /* ---------- op 构造 ---------- */
  function pushOp(op) {
    state.ops.length = state.pointer + 1; // 截断未来
