  }

  /* ---------- 交互动作 ---------- */
  function opFilterValueToggle(dimKey, value, source) {
    var cur = replay(state.pointer).filters[dimKey];
    var all = catValues(dimKey);
    var set = cur && cur.kind === 'values' ? cur.values.slice() : all.slice();
    var idx = set.indexOf(value);
    if (idx >= 0) set.splice(idx, 1); else set.push(value);
    // 保持维度固定顺序
    set.sort(function (a, b) { return all.indexOf(a) - all.indexOf(b); });
    if (set.length === all.length) {
      if (!cur) return; // 本来就无过滤
      pushOp({ type: 'filterClear', dim: dimKey, source: source, phrase: '清除 · ' + DIMS[dimKey].label + ' 过滤' });
    } else if (set.length === 0) {
      pushOp({ type: 'filterClear', dim: dimKey, source: source, phrase: '清空 · ' + DIMS[dimKey].label + '（该维度全部排除）' });
    } else {
      pushOp({ type: 'filter', dim: dimKey, source: source, spec: { kind: 'values', values: set }, phrase: '过滤 · ' + filterPhrase(dimKey, { kind: 'values', values: set }) });
    }
  }
  function opFilterRange(dimKey, lo, hi, source) {
    var ext = EXTENTS[dimKey];
    var full = lo <= ext.lo + 1e-9 && hi >= ext.hi - 1e-9;
    if (full) {
      var cur = replay(state.pointer).filters[dimKey];
      if (!cur) return;
      pushOp({ type: 'filterClear', dim: dimKey, source: source, phrase: '清除 · ' + DIMS[dimKey].label + ' 过滤' });
    } else {
      var spec = { kind: 'range', lo: Math.max(lo, ext.lo), hi: Math.min(hi, ext.hi) };
      pushOp({ type: 'filter', dim: dimKey, source: source, spec: spec, phrase: '过滤 · ' + filterPhrase(dimKey, spec) });
    }
  }
  function opProjection(channel, dimKey, source) {
    var cur = replay(state.pointer).ch[channel];
    if (cur === dimKey) return;
    pushOp({ type: 'projection', channel: channel, dim: dimKey, source: source, phrase: '投影 · ' + channelName(channel) + ' ← ' + DIMS[dimKey].label });
    flashContext();
  }
  function opSelect(ids, source, phraseHint) {
    var cur = replay(state.pointer).sel || [];
    if (cur.length === ids.length && ids.every(function (x) { return cur.indexOf(x) >= 0; })) return;
    var phrase;
    if (ids.length === 0) phrase = '清除选中' + (cur.length ? '（' + cur.length + ' 条）' : '');
    else if (ids.length === 1) phrase = '选中 ' + RECORDS[ids[0]].n;
    else phrase = (phraseHint || '框选') + ' ' + ids.length + ' 条记录';
    pushOp({ type: 'select', ids: ids, source: source, phrase: phrase });
  }
  function opBrushToFilter() {
    var sel = replay(state.pointer).sel || [];
    if (!sel.length) return;
    var ch = replay(state.pointer).ch;
    var box = {};
    [ch.x, ch.y].forEach(function (dk) {
      if (DIMS[dk].type !== 'num') return;
      var lo = Infinity, hi = -Infinity;
      sel.forEach(function (i) { var v = RECORDS[i][dk]; if (v < lo) lo = v; if (v > hi) hi = v; });
      var ext = EXTENTS[dk];
      if (lo > ext.lo + 1e-9 || hi < ext.hi - 1e-9) box[dk] = { lo: lo, hi: hi };
    });
    var keys = Object.keys(box);
    if (!keys.length) return;
    keys.forEach(function (dk) {
      var ext = EXTENTS[dk], pad = (box[dk].hi - box[dk].lo) * 0.02;
      var spec = { kind: 'range', lo: box[dk].lo - pad, hi: box[dk].hi + pad };
      pushOp({ type: 'filter', dim: dk, source: 'brushConvert', spec: spec, phrase: '过滤 · ' + filterPhrase(dk, spec) + '（来自框选）' });
    });
  }
  function channelName(c) { return { x: 'X 轴', y: 'Y 轴', color: '颜色', size: '尺寸' }[c]; }

  /* ---------- 画布 ---------- */
  var canvas, ctx, wrap;
  var pts = []; // 最近一次绘制的命中点 {x,y,r,id}
  var plotRect = { x: 0, y: 0, w: 0, h: 0 };

  function scaleFns(st) {
    var ch = st.ch;
    function makeScale(dimKey) {
      var dim = DIMS[dimKey];
      if (dim.type === 'num') {
