      }
      return { kind: 'cat', values: CAT_AXIS[dimKey], dim: dimKey };
    }
    return { x: makeScale(ch.x), y: makeScale(ch.y) };
  }
  function toPx(scale, v, loPx, sizePx) {
    if (scale.kind === 'num') {
      var t = (v - scale.lo) / (scale.hi - scale.lo);
      return loPx + sizePx * (1 - t); // 注意：调用方决定轴方向
    }
