    var ch = st.ch;

    /* 网格与轴 */
    ctx.font = '11px system-ui, -apple-system, "Segoe UI", sans-serif';
    ctx.textBaseline = 'middle';
    function drawAxis(scale, horizontal) {
      ctx.strokeStyle = '#2c2c2a'; ctx.lineWidth = 1;
      ctx.fillStyle = '#898781';
