            : plotRect.y + plotRect.h * (1 - (tv - scale.lo) / (scale.hi - scale.lo));
          ctx.beginPath();
          if (horizontal) { ctx.moveTo(pos, plotRect.y); ctx.lineTo(pos, plotRect.y + plotRect.h); ctx.textAlign = 'center'; ctx.fillText(fmtVal(tv, scale.dim), pos, plotRect.y + plotRect.h + 12); }
          else { ctx.moveTo(plotRect.x, pos); ctx.lineTo(plotRect.x + plotRect.w, pos); ctx.textAlign = 'right'; ctx.fillText(fmtVal(tv, scale.dim), plotRect.x - 6, pos); }
          ctx.stroke();
        });
      } else {
        scale.values.forEach(function (vv, i) {
          var pos = horizontal
            ? plotRect.x + plotRect.w * ((i + 0.5) / scale.values.length)
            : plotRect.y + plotRect.h * (1 - (i + 0.5) / scale.values.length);
          ctx.beginPath();
          if (horizontal) { ctx.moveTo(pos, plotRect.y); ctx.lineTo(pos, plotRect.y + plotRect.h); ctx.textAlign = 'center'; ctx.fillText(vv, pos, plotRect.y + plotRect.h + 12); }
          else { ctx.moveTo(plotRect.x, pos); ctx.lineTo(plotRect.x + plotRect.w, pos); ctx.textAlign = 'right'; ctx.fillText(vv, plotRect.x - 6, pos); }
