      }
    }
    drawAxis(sx, true); drawAxis(sy, false);
    // 轴基线
    ctx.strokeStyle = '#383835';
    ctx.strokeRect(plotRect.x + 0.5, plotRect.y + 0.5, plotRect.w, plotRect.h);
    // 轴题
    ctx.fillStyle = '#c3c2b7'; ctx.textAlign = 'center';
    ctx.fillText(withUnit('', ch.x) === '' ? DIMS[ch.x].label : DIMS[ch.x].label + (DIMS[ch.x].unit ? '（' + DIMS[ch.x].unit + '）' : ''), plotRect.x + plotRect.w / 2, plotRect.y + plotRect.h + 28);
    ctx.save();
    ctx.translate(14, plotRect.y + plotRect.h / 2); ctx.rotate(-Math.PI / 2);
