        sy.kind === 'num' ? (rec[ch.y] - sy.lo) / (sy.hi - sy.lo) : (CAT_AXIS[ch.y].indexOf(rec[ch.y]) + 0.5) / CAT_AXIS[ch.y].length);
      if (px < plotRect.x - 2 || px > plotRect.x + plotRect.w + 2 || py < plotRect.y - 2 || py > plotRect.y + plotRect.h + 2) return;
      var tSize = sExt ? (rec[ch.size] - sExt.lo) / (sExt.hi - sExt.lo) : 0.5;
      var pr = 2.6 + 3.9 * Math.sqrt(Math.max(0, Math.min(1, tSize)));
