      var groups = [
        { id: 'cat', title: '分类维度' },
        { id: 'num', title: '数值维度' },
      ];
      var html = '';
      groups.forEach(function (g) {
        html += '<div class="shelf-group"><div class="shelf-title">' + g.title + '</div>';
        ALL_DIMS.forEach(function (k) {
          if (DIMS[k].group !== g.id) return;
          html += '<div class="dim-row" data-dim="' + k + '">' +
            '<button class="dim-head" data-dim="' + k + '" aria-expanded="false">' +
            '<span class="dim-name">' + DIMS[k].label + '</span>' +
