      meta.textContent = '';
      var badge = activeFilterBadge(st, k);
      if (badge) { var b = el('span', 'badge filter-badge', badge); meta.appendChild(b); }
      Object.keys(st.ch).forEach(function (channel) {
        if (st.ch[channel] !== k) return;
