    });
  }

  function updateDimBody(st, k, body, rebuild) {
    var dim = DIMS[k];
    if (rebuild || !body.dataset.builtDim) {
      body.dataset.builtDim = k + ':' + dim.type;
      var html = '<div class="dim-tools">';
      ['x', 'y', 'color', 'size'].forEach(function (c) {
        if (c === 'size' && dim.type !== 'num') return;
        html += '<button data-action="bind" data-channel="' + c + '" data-dim="' + k + '" title="装入 ' + channelName(c) + '">' + { x: 'X', y: 'Y', color: '色', size: '寸' }[c] + '</button>';
      });
      html += '</div>';
      if (dim.type === 'cat') {
        html += '<div class="val-list"></div>';
      } else {
        html += '<div class="range-ctrl" data-dim="' + k + '">' +
          '<div class="range-nums">' +
          '<input type="number" data-role="range" data-dim="' + k + '" data-bound="lo" step="any" aria-label="' + dim.label + ' 最小值">' +
          '<span class="range-sep">–</span>' +
          '<input type="number" data-role="range" data-dim="' + k + '" data-bound="hi" step="any" aria-label="' + dim.label + ' 最大值">' +
          '</div>' +
          '<input type="range" class="rg lo" data-role="range" data-dim="' + k + '" data-bound="lo" aria-label="' + dim.label + ' 范围下界">' +
          '<input type="range" class="rg hi" data-role="range" data-dim="' + k + '" data-bound="hi" aria-label="' + dim.label + ' 范围上界">' +
          '</div>';
      }
      body.innerHTML = html;
    }
    var chB = body.querySelector('.dim-tools');
    if (chB) Array.prototype.forEach.call(chB.querySelectorAll('button'), function (btn) {
      btn.classList.toggle('on', st.ch[btn.dataset.channel] === k);
    });
    if (dim.type === 'cat') {
      var spec = st.filters[k];
      var list = body.querySelector('.val-list');
      var counts = {};
      RECORDS.forEach(function (r) { counts[r[k]] = (counts[r[k]] || 0) + 1; });
      list.innerHTML = catValues(k).map(function (v) {
        var active = !spec || (spec.kind === 'values' && spec.values.indexOf(v) >= 0);
        return '<button data-action="value" data-dim="' + k + '" data-value="' + v + '" aria-pressed="' + active + '" class="val-btn' + (active ? '' : ' off') + '">' +
          '<span class="swatch" style="background:' + colorOf(k, v) + '"></span>' + v +
          '<span class="val-count">' + counts[v] || 0 + '</span><span class="val-count">' + (counts[v] || 0) + '</span></button>';
      }).join('');
    } else {
      var ext = EXTENTS[k];
      var specN = st.filters[k];
      var lo = specN && specN.kind === 'range' ? specN.lo : ext.lo;
      var hi = specN && specN.kind === 'range' ? specN.hi : ext.hi;
      var loI = body.querySelector('[data-bound="lo"]'), hiI = body.querySelector('[data-bound="hi"]');
      ['number', 'range'].forEach(function (type) {
        body.querySelectorAll('input[type="' + type + '"]').forEach(function (inp) {
          var bound = inp.dataset.bound;
          var min = type === 'range' ? ext.lo : undefined, max = type === 'range' ? ext.hi : undefined;
          if (min != null) inp.min = min;
          if (max != null) inp.max = max;
          inp.step = type === 'range' ? (ext.hi - ext.lo) / 200 : 'any';
          inp.value = bound === 'lo' ? lo : hi;
        });
      });
    }
  }

  function renderLegend(st, visible) {
    var box = $('legend');
    var dimKey = st.ch.color;
    var dim = DIMS[dimKey];
    var spec = st.filters[dimKey];
    var counts = {};
    visible.forEach(function (r) { var v = r[dimKey]; counts[v] = (counts[v] || 0) + 1; });
    var html = '<div class="legend-title">颜色 · ' + dim.label + '</div>';
    if (dim.type === 'cat') {
      html += catValues(dimKey).map(function (v, i) {
        var active = !spec || (spec.kind === 'values' && spec.values.indexOf(v) >= 0);
        var shape = shapeOf(dimKey, v);
        return '<button class="legend-row' + (active ? '' : ' off') + '" data-value="' + v + '" aria-pressed="' + active + '" title="点击 过滤/恢复 「' + v + '」">' +
          '<svg width="14" height="14" viewBox="0 0 14 14" aria-hidden="true">' + swatchSvg(shape, colorOf(dimKey, v)) + '</svg>' +
          '<span class="legend-name">' + v + '</span><span class="legend-count">' + (counts[v] || 0) + '</span></button>';
      }).join('');
    } else {
      html += '<div class="legend-ramp" aria-hidden="true"></div>' +
        '<div class="legend-range"><span>' + fmtVal(EXTENTS[dimKey].lo, dimKey) + '</span><span>' + fmtVal(EXTENTS[dimKey].hi, dimKey) + (dim.unit ? ' ' + dim.unit : '') + '</span></div>';
    }
    box.innerHTML = html;
    box.classList.toggle('num', dim.type === 'num');
    Array.prototype.forEach.call(box.querySelectorAll('button.legend-row'), function (btn) {
      btn.addEventListener('click', function () { opFilterValueToggle(dimKey, btn.dataset.value, 'legend'); });
    });
  }
  function swatchSvg(shape, color) {
    if (shape === 'circle') return '<circle cx="7" cy="7" r="4.4" fill="' + color + '" stroke="#1a1a19" stroke-width="1"/>';
    if (shape === 'square') return '<rect x="2.6" y="2.6" width="8.8" height="8.8" fill="' + color + '" stroke="#1a1a19" stroke-width="1"/>';
    if (shape === 'triangle') return '<path d="M7 1.8 L12.6 11.6 L1.4 11.6 Z" fill="' + color + '" stroke="#1a1a19" stroke-width="1"/>';
    if (shape === 'diamond') return '<path d="M7 1.4 L12.4 7 L7 12.6 L1.6 7 Z" fill="' + color + '" stroke="#1a1a19" stroke-width="1"/>';
    if (shape === 'cross') return '<path d="M3 3 L11 11 M11 3 L3 11" stroke="' + color + '" stroke-width="2.2" fill="none"/>';
    return '<circle cx="7" cy="7" r="4" fill="none" stroke="' + color + '" stroke-width="2.4"/>';
  }

  function renderInspector(st) {
    var box = $('detail');
    var sel = st.sel || [];
    if (!sel.length) {
      box.innerHTML = '<div class="detail-empty"><div class="detail-empty-title">未选中记录</div>' +
        '<p>点击画布中的点查看全维度明细；<br>拖拽框选可一次选中多条。</p>' +
        '<p class="detail-hint">选中会跨维度切换保留。</p></div>';
      return;
    }
    if (sel.length === 1) {
      var rec = RECORDS[sel[0]];
      var rows = ALL_DIMS.map(function (k) {
        var v = rec[k];
        return '<div class="kv"><span class="k">' + DIMS[k].label + '</span><span class="v">' +
          (DIMS[k].type === 'num' ? withUnit(v, k) : v) + '</span></div>';
      }).join('');
      var host = hostOf(rec.n);
      var siblings = RECORDS.filter(function (r) { return r.n !== rec.n && hostOf(r.n) === host; });
      var sibHtml = '';
      if (siblings.length) {
        sibHtml = '<div class="detail-sub">同恒星系（' + host + '）</div>' + siblings.map(function (r) {
          return '<button class="sib" data-id="' + r.i + '">' + r.n + ' · ' + r.pc + '</button>';
        }).join('');
      }
      box.innerHTML = '<div class="detail-head"><span class="detail-name">' + rec.n + '</span>' +
        '<span class="detail-host">' + host + '</span></div>' +
        '<div class="detail-tags"><span class="tag">' + rec.ms + '</span><span class="tag">' + instrumentOf(rec) + '</span></div>' +
        rows + sibHtml;
      Array.prototype.forEach.call(box.querySelectorAll('button.sib'), function (btn) {
        btn.addEventListener('click', function () { opSelect([+btn.dataset.id], 'inspector', '选中'); });
      });
    } else {
      var byClass = {};
      sel.forEach(function (i) { var c = RECORDS[i].pc; byClass[c] = (byClass[c] || 0) + 1; });
      var maxC = Math.max.apply(null, Object.keys(byClass).map(function (k) { return byClass[k]; }));
      var bars = catValues('pc').map(function (c) {
        var n = byClass[c] || 0;
        return '<div class="mini-row"><span class="mini-label">' + c + '</span>' +
          '<span class="mini-bar"><span style="width:' + (maxC ? (n / maxC * 100) : 0) + '%;background:' + colorOf('pc', c) + '"></span></span>' +
          '<span class="mini-n">' + n + '</span></div>';
      }).join('');
      var names = sel.slice(0, 8).map(function (i) { return RECORDS[i].n; }).join('、');
      box.innerHTML = '<div class="detail-head"><span class="detail-name">已选 ' + sel.length + ' 条</span></div>' +
        bars +
        '<div class="detail-sub">记录</div><div class="detail-names">' + names + (sel.length > 8 ? ' …' : '') + '</div>' +
        '<div class="detail-hint">可用「框选转过滤」把选区固化为 X/Y 范围过滤。</div>';
    }
  }

  function renderTrail(st) {
    var box = $('trail-chips');
    box.textContent = '';
    state.ops.forEach(function (op, i) {
      var past = i <= state.pointer;
      var chip = el('button', 'chip kind-' + op.type + (past ? '' : ' future') + (op.disabled ? ' disabled' : ''));
      chip.dataset.opId = op.id;
      chip.setAttribute('aria-haspopup', 'dialog');
      var kindTxt = { filter: '过滤', filterClear: '过滤', projection: '投影', select: '选中' }[op.type];
      chip.appendChild(el('span', 'chip-kind', kindTxt));
      chip.appendChild(el('span', 'chip-text', op.phrase));
      chip.appendChild(el('span', 'chip-src', sourceLabel(op.source)));
      if (op.disabled) chip.appendChild(el('span', 'chip-dis', '已禁用'));
      box.appendChild(chip);
    });
    $('trail-count').textContent = state.ops.length ? ('第 ' + (state.pointer + 1) + ' / ' + state.ops.length + ' 步') : '尚无操作';
    $('btn-undo').disabled = state.pointer < 0;
    $('btn-redo').disabled = state.pointer >= state.ops.length - 1;
    box.scrollLeft = box.scrollWidth;
  }

  function renderStats(st, visible) {
    $('stat-visible').textContent = '可见 ' + visible.length + ' / ' + RECORDS.length;
    var nFilters = Object.keys(st.filters).length;
    var nSel = (st.sel || []).length;
    $('stat-context').textContent = '上下文：' + nFilters + ' 过滤 · ' + nSel + ' 选中（跨投影保留）· 轨迹 ' + (state.pointer + 1) + ' 步';
  }

  var flashTimer = null;
  function flashContext() {
    var f = $('ctx-flash');
    f.hidden = false;
    f.textContent = '维度已切换 · 过滤与选中已保留';
    clearTimeout(flashTimer);
    flashTimer = setTimeout(function () { f.hidden = true; }, 1800);
  }

  /* ---------- 表格视图（对比/扫读 + 无障碍备选） ---------- */
  function renderTable(st, visible) {
    var tv = $('table-view');
    if (!UI.tableView) { tv.hidden = true; return; }
    tv.hidden = false;
    var cols = ['n'].concat(ALL_DIMS);
    var head = '<tr><th>行星</th>' + ALL_DIMS.map(function (k) { return '<th>' + DIMS[k].label + '</th>'; }).join('') + '</tr>';
    var maxRows = 200;
    var rows = visible.slice(0, maxRows).map(function (r) {
      return '<tr><td class="tn">' + r.n + '</td>' + ALL_DIMS.map(function (k) {
        return '<td' + (st.ch.color === k ? ' class="tc"' : '') + '>' + fmtVal(r[k], k) + '</td>';
      }).join('') + '</tr>';
    }).join('');
    tv.innerHTML = '<div class="tv-head"><strong>数据表</strong><span>可见 ' + visible.length + ' 条' + (visible.length > maxRows ? '，显示前 ' + maxRows + ' 条' : '') + '</span>' +
      '<button id="tv-close">关闭表格</button></div>' +
      '<div class="tv-scroll"><table>' + '<thead>' + head + '</thead><tbody>' + rows + '</tbody></table></div>';
    $('tv-close').addEventListener('click', function () { UI.tableView = false; renderTable(st, visible); $('btn-table').setAttribute('aria-pressed', 'false'); });
  }

  /* ---------- 主渲染 ---------- */
  var rafPending = false;
  function render() {
    if (rafPending) return;
    rafPending = true;
    requestAnimationFrame(function () {
      rafPending = false;
      var st = replay(state.pointer);
      var visible = RECORDS.filter(function (r) { return matchesFilters(r, st.filters); });
      var selSet = new Set(st.sel || []);
      drawPlot(st, visible, selSet);
      renderChannelBar(st, visible.length);
      renderShelf(st);
      renderLegend(st, visible);
      renderInspector(st);
      renderTrail(st);
      renderStats(st, visible);
      renderTable(st, visible);
      // 空态
      var empty = $('empty-overlay');
      if (visible.length === 0 && !UI.tableView) {
        empty.hidden = false;
      } else {
        empty.hidden = true;
      }
    });
  }

  /* ---------- 画布交互 ---------- */
  function bindCanvas(st0) {
    function pos(ev) {
      var rect = canvas.getBoundingClientRect();
      return { x: ev.clientX - rect.left, y: ev.clientY - rect.top };
    }
    function nearest(p, maxDist) {
      var best = null, bd = maxDist * maxDist;
      pts.forEach(function (pt) {
        var dx = pt.x - p.x, dy = pt.y - p.y, d2 = dx * dx + dy * dy;
        if (d2 <= bd && (best === null || d2 < bd)) { best = pt; bd = d2; }
      });
      return best;
    }
    var down = null;
    canvas.addEventListener('pointerdown', function (ev) {
      if (ev.button !== 0) return;
      var p = pos(ev);
      down = { x0: p.x, y0: p.y, moved: false };
      canvas.setPointerCapture(ev.pointerId);
    });
    canvas.addEventListener('pointermove', function (ev) {
      var p = pos(ev);
      if (down) {
        if (Math.abs(p.x - down.x0) + Math.abs(p.y - down.y0) > 6) down.moved = true;
        if (down.moved) {
          UI.brush = { active: true, x0: down.x0, y0: down.y0, x1: p.x, y1: p.y };
          render();
        }
        return;
      }
      var hit = nearest(p, 9);
      var newHover = hit ? hit.id : null;
      var tip = $('tooltip');
      if (newHover !== UI.hoverId) {
        UI.hoverId = newHover;
        canvas.style.cursor = hit ? 'pointer' : 'default';
        if (hit) {
          var st = replay(state.pointer);
          var r = hit.rec;
          tip.innerHTML = '<strong>' + r.n + '</strong><span>' + hostOf(r.n) + ' · ' + r.ms + '</span>' +
            '<span>' + DIMS[st.ch.x].label + ' ' + withUnit(r[st.ch.x], st.ch.x) + ' · ' + DIMS[st.ch.y].label + ' ' + withUnit(r[st.ch.y], st.ch.y) + '</span>' +
            '<span>' + DIMS[st.ch.color].label + '：' + r[st.ch.color] + '</span>';
          tip.hidden = false;
          var tw = tip.offsetWidth, thh = tip.offsetHeight;
          tip.style.left = Math.min(wrap.clientWidth - tw - 8, Math.max(4, hit.x + 12)) + 'px';
          tip.style.top = Math.min(wrap.clientHeight - thh - 8, Math.max(4, hit.y - thh - 10)) + 'px';
        } else tip.hidden = true;
        render();
      } else if (hit) {
        var st2 = replay(state.pointer);
        var r2b = hit.rec;
        tip.innerHTML = '<strong>' + r2b.n + '</strong><span>' + hostOf(r2b.n) + ' · ' + r2b.ms + '</span>' +
          '<span>' + DIMS[st2.ch.x].label + ' ' + withUnit(r2b[st2.ch.x], st2.ch.x) + ' · ' + DIMS[st2.ch.y].label + ' ' + withUnit(r2b[st2.ch.y], st2.ch.y) + '</span>' +
          '<span>' + DIMS[st2.ch.color].label + '：' + r2b[st2.ch.color] + '</span>';
      }
    });
    canvas.addEventListener('pointerup', function (ev) {
      if (!down) return;
      var p = pos(ev);
      var wasMoved = down.moved;
      down = null;
      if (wasMoved && UI.brush && UI.brush.active) {
        var b = UI.brush;
        UI.brush = null;
        var x0 = Math.min(b.x0, b.x1), x1 = Math.max(b.x0, b.x1), y0 = Math.min(b.y0, b.y1), y1 = Math.max(b.y0, b.y1);
        var st = replay(state.pointer);
        var ids = pts.filter(function (pt) {
          return pt.x >= x0 && pt.x <= x1 && pt.y >= y0 && pt.y <= y1 &&
            RECORDS.filter(function (r) { return matchesFilters(r, st.filters); }).hasOwnProperty;
        }).map(function (pt) { return pt.id; });
        opSelect(ids, 'brush');
        render();
      } else if (!wasMoved) {
        var hit = nearest(p, 9);
        if (hit) opSelect([hit.id], 'click');
        else {
          var cur = replay(state.pointer).sel || [];
          if (cur.length) opSelect([], 'click');
        }
      }
      if (UI.brush) { UI.brush = null; render(); }
    });
    canvas.addEventListener('pointerleave', function () {
      $('tooltip').hidden = true;
      if (UI.hoverId != null) { UI.hoverId = null; render(); }
    });
  }

  /* ---------- 轨迹 chip 弹层（归属详情） ---------- */
  function closePopover() {
    var pop = $('chip-pop');
    pop.hidden = true;
    UI.popoverOpId = null;
  }
  function openPopover(opId, anchor) {
    var op = state.ops.filter(function (o) { return o.id === opId; })[0];
    if (!op) return;
    var pop = $('chip-pop');
    var idx = state.ops.indexOf(op);
    var past = idx <= state.pointer;
    var rows = [
      ['来源控件', sourceLabel(op.source)],
      ['操作类型', { filter: '过滤', filterClear: '清除过滤', projection: '投影通道', select: '选中集' }[op.type]],
      ['目标维度', op.dim ? DIMS[op.dim].label + (op.channel ? '（' + channelName(op.channel) + ' 通道）' : '') : (op.type === 'select' ? '选中集（' + op.ids.length + ' 条记录）' : '—')],
      ['取值', op.spec ? (op.spec.kind === 'values' ? op.spec.values.join('、') : fmtVal(op.spec.lo, op.dim) + ' – ' + fmtVal(op.spec.hi, op.dim)) : (op.type === 'select' ? op.ids.slice(0, 6).map(function (i) { return RECORDS[i].n; }).join('、') + (op.ids.length > 6 ? ' …' : '') : op.dim ? DIMS[op.dim].label : '—')],
      ['轨迹位置', '第 ' + (idx + 1) + ' 步 / 共 ' + state.ops.length + ' 步'],
      ['当前状态', op.disabled ? '已禁用（不参与过滤/选中）' : past ? '生效中' : '未来步骤（可前进到此）'],
    ];
    pop.innerHTML = '<div class="pop-title">' + op.phrase + '</div>' +
      rows.map(function (r) { return '<div class="kv"><span class="k">' + r[0] + '</span><span class="v">' + r[1] + '</span></div>'; }).join('') +
      '<div class="pop-actions">' +
      (op.type === 'filter' || op.type === 'select' ? '<button data-act="toggle">' + (op.disabled ? '启用' : '禁用') + '</button>' : '') +
      (past ? '<button data-act="revert">回退到此步</button>' : '<button data-act="forward">前进到此步</button>') +
      '<button data-act="close">关闭</button></div>';
    pop.hidden = false;
    UI.popoverOpId = opId;
    var pr = pop.getBoundingClientRect();
    var left = Math.min(window.innerWidth - pr.width - 8, Math.max(8, anchor.getBoundingClientRect().left));
    pop.style.left = left + 'px';
    pop.style.top = Math.max(8, anchor.getBoundingClientRect().top - pr.height - 8) + 'px';
    Array.prototype.forEach.call(pop.querySelectorAll('button'), function (btn) {
      btn.addEventListener('click', function (ev) {
        ev.stopPropagation();
        var act = btn.dataset.act;
        if (act === 'toggle') { op.disabled = !op.disabled; render(); closePopover(); }
        else if (act === 'revert') { state.pointer = idx; render(); closePopover(); }
        else if (act === 'forward') { state.pointer = idx; render(); closePopover(); }
        else closePopover();
      });
    });
    var first = pop.querySelector('button');
    if (first) first.focus();
  }

  /* ---------- 事件绑定 ---------- */
  function bindChrome() {
    $('btn-undo').addEventListener('click', function () { if (state.pointer >= 0) { state.pointer--; render(); } });
    $('btn-redo').addEventListener('click', function () { if (state.pointer < state.ops.length - 1) { state.pointer++; render(); } });
    $('btn-reset').addEventListener('click', function () { state.pointer = -1; render(); });
    $('btn-brush-filter').addEventListener('click', function () { opBrushToFilter(); });
    $('btn-clear-sel').addEventListener('click', function () { opSelect([], 'keyboard'); });
    $('btn-table').addEventListener('click', function () {
      UI.tableView = !UI.tableView;
      this.setAttribute('aria-pressed', String(UI.tableView));
      render();
    });
    $('btn-empty-undo').addEventListener('click', function () { if (state.pointer >= 0) { state.pointer--; render(); } });
    $('btn-empty-reset').addEventListener('click', function () { state.pointer = -1; render(); });
    $('trail-chips').addEventListener('click', function (ev) {
      var chip = ev.target.closest('.chip');
      if (!chip) return;
      if (UI.popoverOpId === chip.dataset.opId) { closePopover(); return; }
      openPopover(chip.dataset.opId, chip);
    });
    document.addEventListener('click', function (ev) {
      var pop = $('chip-pop');
      if (!pop.hidden && !pop.contains(ev.target) && !ev.target.closest('.chip')) closePopover();
    });
    document.addEventListener('keydown', function (ev) {
      var mod = ev.ctrlKey || ev.metaKey;
      if (mod && !ev.shiftKey && ev.key.toLowerCase() === 'z') { ev.preventDefault(); if (state.pointer >= 0) { state.pointer--; render(); } }
      else if ((mod && ev.shiftKey && ev.key.toLowerCase() === 'z') || (mod && ev.key.toLowerCase() === 'y')) { ev.preventDefault(); if (state.pointer < state.ops.length - 1) { state.pointer++; render(); } }
      else if (ev.key === 'Escape') {
        if (!$('chip-pop').hidden) { closePopover(); return; }
        if (UI.brush) { UI.brush = null; render(); return; }
        if ((replay(state.pointer).sel || []).length) opSelect([], 'keyboard');
      }
    });
    window.addEventListener('resize', render);
    if (window.ResizeObserver) new ResizeObserver(function () { render(); }).observe(wrap);
  }

  /* ---------- 初始化（同步：数据内联，无加载等待） ---------- */
  function init() {
    document.body.dataset.appState = 'loading';
    canvas = $('plot'); ctx = canvas.getContext('2d'); wrap = $('canvas-wrap');
    bindChrome();
    bindCanvas();
    render();
    document.body.dataset.appState = 'ready';
  }
  try {
    init();
  } catch (err) {
    document.body.dataset.appState = 'error';
    var b = $('err-banner');
    b.hidden = false;
    b.textContent = '应用初始化失败：' + err.message;
  }
  window.addEventListener('error', function (ev) {
    document.body.dataset.appState = 'error';
    var b = $('err-banner');
    b.hidden = false;
    b.textContent = '运行时错误：' + (ev.message || '未知');
  });
})();

