    chip.appendChild(el('span', 'chip-kind', kindTxt));
    chip.appendChild(el('span', 'chip-text', op.phrase));
    chip.appendChild(el('span', 'chip-src', sourceLabel(op.source)));
    if (op.disabled) chip.appendChild(el('span', 'chip-dis', '已禁用'));
    box.appendChild(chip);
  });
  $('trail-count').textContent = state.ops.length ? ('第 ' + (state.pointer + 1) + ' / ' + state.ops.length + ' 步') : '尚无操作';
